cardCss:
/* ==========================================================================
   English Word Card · 轻立体 + 翡翠（在原有布局上只换外观）
   --------------------------------------------------------------------------
   · 版式/尺寸/DOM 与原模板一致：44px 圆钮 · 14px 18px 内边距 · 16px 圆角 ·
     260px 最小高 · 4px 左脊 · 单块 .definition · 例句区 · 各字段字号公式。
     本次只改：颜色、描边、投影、渐变、文本色。
   · 颜色全部走 --ew-* 变量；暗色皮肤只重映射变量，规则一条不改。
   · 配色 = 简化版同款「乙 · 翡翠」：主色 emerald #059669 → cyan #0891b2。
   ========================================================================== */

/* ---------- 1. 卡面：轻浮起 + 右上角淡主色光晕 + 左侧双色渐变脊 ---------- */
.word-card {
  /* --- 版式（与原模板逐字一致，未改） --- */
  border-radius: 16px;
  padding: 14px 18px;
  min-height: 260px; display: flex; flex-direction: column;
  transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
  margin-bottom: 16px;

  /* --- 配色 token --- */
  --ew-h1:#059669; --ew-h2:#0891b2;                    /* 主色 / 第二色 */
  /* 内容倍率：徽章/音标胶囊这类「跟着字走」的盒子用它换算尺寸 */
  --ew-idx: calc(var(--scale-basic, 1) * var(--card-font-scale, 1));
  --ew-h1-deep:#065f46; --ew-h1-soft:#ecfdf5;
  --ew-h1-sh:rgba(5,150,105,.34);
  --ew-ink:#065f46;                                    /* 单词 */
  --ew-warm-ink:#9a3412;                               /* 中文释义：暖色墨水 */
  --ew-def-bg:#f4faf8; --ew-def-bar:#059669;
  --ew-ex-bg:#fefaf0;  --ew-ex-bar:#f0b429;
  --ew-divider:linear-gradient(90deg,rgba(5,150,105,.30) 0%,rgba(8,145,178,.12) 55%,rgba(15,23,42,0) 100%);
  --ew-c1:#ffffff; --ew-c2:#fcfdff;
  --ew-card-line:rgba(15,23,42,.07);
  --ew-card-sh:0 1px 2px rgba(15,23,42,.045),0 10px 22px -15px rgba(15,23,42,.26);
  --ew-card-sh-up:0 2px 4px rgba(15,23,42,.05),0 18px 32px -18px rgba(15,23,42,.32);
  --ew-btn-line:#e2e8f0; --ew-btn-sh:0 1.5px 3px rgba(15,23,42,.07);
  --ew-play:#059669; --ew-play-bg:#ecfdf5; --ew-play-line:#a7f3d0; --ew-play-sh:rgba(5,150,105,.30);
  --ew-eye:#0891b2;  --ew-eye-bg:#ecfeff;  --ew-eye-line:#a5f3fc;  --ew-eye-sh:rgba(8,145,178,.30);
  --ew-mark:#e11d48; --ew-mark-bg:#fff1f2; --ew-mark-line:#fecdd3; --ew-mark-sh:rgba(225,29,72,.30);
  --ew-fav:#d97706;  --ew-fav-bg:#fffbeb;  --ew-fav-line:#fde68a;  --ew-fav-sh:rgba(217,119,6,.30);

  /* --- 外观 ---
     左脊 = 4px 透明边框 + 背景渐变条。border-left 原本就是 4px，
     所以盒子几何与原来**完全一致**，只是纯色换成了渐变。 */
  background:
    linear-gradient(180deg,var(--ew-h1) 0%,var(--ew-h2) 100%) left top / 4px 100% no-repeat,
    radial-gradient(125% 100% at 100% 0%, var(--ew-h1-soft) 0%, rgba(255,255,255,0) 60%),
    linear-gradient(180deg,var(--ew-c1) 0%,var(--ew-c2) 100%);
  border: 1px solid var(--ew-card-line);
  border-left: 4px solid transparent;
  box-shadow: var(--ew-card-sh);
}
.word-card:hover {
  transform: translateY(-3px);                 /* 与原模板一致 */
  box-shadow: var(--ew-card-sh-up);
  border-color: var(--ew-card-line);           /* 不再换成 --primary-soft，免得抢左脊 */
}
.word-card.highlighted {
  background:
    linear-gradient(180deg,#e11d48 0%,#f43f5e 100%) left top / 4px 100% no-repeat,
    radial-gradient(125% 100% at 100% 0%, rgba(244,63,94,.10) 0%, rgba(255,255,255,0) 60%),
    linear-gradient(180deg,#fff8f9 0%,#fffdfd 100%);
}
.word-card:active { transform: scale(0.99); }
.word-card.enter { animation: cardIn 0.5s both; }
@keyframes cardIn {
  from { opacity: 0; transform: translateY(14px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}

/* ---------- 2. 头部：序号徽章 / 单词 / 音标药丸 ---------- */
/* .card-header / .word-basic 的行距、间距、字号公式一律不动 */
.card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; gap: 8px; }
.word-basic { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
/* 序号徽章是一枚"胶囊"，它的尺寸必须跟着字号走。
   字号乘了 --card-font-scale，盒子却写死 20px 高 —— 160% 时 19.2px 的字塞进 20px
   的盒子里，基线被挤到盒底，数字看着像"错位"，圆角还会切到笔画。
   这里把 字号/高/最小宽/内边距/圆角/字距 全部交给同一个倍率 --ew-idx 驱动：
   倍率在 100% 时正好等于 1（逐项等于原值，几何零变化），放大时整枚徽章等比放大。 */
.word-index {
  display: inline-grid; place-items: center; flex: 0 0 auto;
  min-width: calc(22px * var(--ew-idx));
  height: calc(20px * var(--ew-idx));
  padding: 0 calc(6px * var(--ew-idx));
  border-radius: calc(7px * var(--ew-idx));
  color: #fff; font-weight: 800; letter-spacing: calc(.3px * var(--ew-idx));
  background: linear-gradient(135deg,var(--ew-h1) 0%,var(--ew-h2) 100%);
  box-shadow: 0 3px 8px -2px var(--ew-h1-sh);
  font-size: calc(12px * var(--ew-idx));
}
.word-title {
  font-weight: var(--card-font-weight, 700); color: var(--ew-ink); letter-spacing: -0.3px;
  font-size: calc(22px * var(--scale-basic, 1) * var(--card-font-scale, 1));
}
.word-phonetic {
  color: var(--ew-h1-deep); background: var(--ew-h1-soft);
  border-radius: 9999px;
  padding: calc(1px * var(--ew-idx)) calc(9px * var(--ew-idx)); font-weight: 600;
  font-size: calc(13px * var(--scale-basic, 1) * var(--card-font-scale, 1));
}

/* ---------- 3. 按钮：四个动作四种语义色，浅底描边 → hover 实心 ---------- */
/* 按钮 44px 不变；只在应用字号被调大时跟着放大（默认 100% 时 = 44px，几何不变） */
.word-card { --ew-scale: clamp(1,(var(--card-font-scale,1) - 1)*.55 + 1,1.45); --ew-btn: calc(44px*var(--ew-scale)); }
.actions { display: flex; gap: 10px; }
.action-btn {
  cursor: pointer;
  width: var(--ew-btn); height: var(--ew-btn);
  display: flex; align-items: center; justify-content: center;
  border-radius: 90px; background: #ffffff; color: var(--ink-3, #64748b);
  border: 1.5px solid var(--ew-btn-line);
  box-shadow: var(--ew-btn-sh), inset 0 1px 0 rgba(255,255,255,.9);
  transition: transform .16s cubic-bezier(.2,.7,.3,1), box-shadow .16s,
              background .16s, color .16s, border-color .16s;
}
.action-btn svg { width: 28px; height: 28px; }
.action-btn svg, .action-btn i { transition: transform 0.18s; }
/* 光学居中：FA7 字形在 em 方框里系统性偏上，只让 <i> 盒子居中是治不好的。
   注意本模板的图标与简化版相反：act-mark = 星星、act-fav = 书签，
   所以补偿值不同（实测星星偏上 0.077em、书签偏上 0.127em）。 */
.action-btn i { display: block; line-height: 1; font-size: calc(18px * var(--ew-scale)); transform: translateY(.125em); }
.action-btn.act-mark i { transform: translateY(.077em); }
.action-btn.act-fav i  { transform: translateY(.127em); }
.action-btn:hover { transform: translateY(-2px); }
.action-btn:hover svg { transform: scale(1.12); }
.action-btn:active { transform: scale(0.88); }

.action-btn.act-play { color: var(--ew-play); background: var(--ew-play-bg); border-color: var(--ew-play-line); }
.action-btn.act-eye  { color: var(--ew-eye);  background: var(--ew-eye-bg);  border-color: var(--ew-eye-line); }
.action-btn.act-mark { color: var(--ew-mark); background: var(--ew-mark-bg); border-color: var(--ew-mark-line); }
.action-btn.act-fav  { color: var(--ew-fav);  background: var(--ew-fav-bg);  border-color: var(--ew-fav-line); }

.action-btn.act-play:hover { background: var(--ew-play); color: #fff; border-color: var(--ew-play);
                             box-shadow: 0 7px 15px -4px var(--ew-play-sh); }
.action-btn.act-eye:hover  { background: var(--ew-eye);  color: #fff; border-color: var(--ew-eye);
                             box-shadow: 0 7px 15px -4px var(--ew-eye-sh); }
.action-btn.act-mark:hover { background: var(--ew-mark); color: #fff; border-color: var(--ew-mark);
                             box-shadow: 0 7px 15px -4px var(--ew-mark-sh); }
.action-btn.act-fav:hover  { background: var(--ew-fav);  color: #fff; border-color: var(--ew-fav);
                             box-shadow: 0 7px 15px -4px var(--ew-fav-sh); }

.action-btn.act-mark.is-active { background: var(--ew-mark); border-color: var(--ew-mark); color: #fff;
                                 box-shadow: 0 5px 13px -3px var(--ew-mark-sh); }
.action-btn.act-fav.is-active  { background: var(--ew-fav);  border-color: var(--ew-fav);  color: #fff;
                                 box-shadow: 0 5px 13px -3px var(--ew-fav-sh); }
.action-btn.act-eye.is-active  { background: var(--ew-eye);  border-color: var(--ew-eye);  color: #fff;
                                 box-shadow: 0 5px 13px -3px var(--ew-eye-sh); }

/* ---------- 4. 释义块（单块，中英同宽同起点） ---------- */
/* 左侧那道色条用 inset 阴影画，不占盒宽 → 文本起点与原来一模一样 */
.definition {
  margin-bottom: 6px; padding: 6px 8px; border-radius: 8px;
  background: var(--ew-def-bg);
  box-shadow: inset 3px 0 0 var(--ew-def-bar);
}
/* 未标记的卡：英文与中文两个 div 都是 .hide（cardJs 的偷看逻辑），
   但块本身还在 —— 空块上画那条色条会变成一个奇怪的小钩子，所以有内容才画。
   （不收缩高度：这样标记/取消标记时卡片高度不跳。） */
.definition:not(:has(> div:not(.hide))) { background: none; box-shadow: none; }
.def-en {
  color: var(--ink, #1d1d1d); line-height: 1.4; margin-bottom: 3px;
  font-size: calc(13px * var(--scale-def, 1) * var(--card-font-scale, 1));
}
.def-cn {
  color: var(--ew-warm-ink); line-height: 1.4;
  font-size: calc(13px * var(--scale-def, 1) * var(--card-font-scale, 1));
}

/* ---------- 5. 分隔线 + 例句区 ---------- */
.divider { height: 1px; background-color: var(--line, #e6e6e6); background: var(--ew-divider); margin: 6px 0; }

.examples { display: flex; flex-direction: column; gap: 6px; }
.example-item {
  display: flex; flex-direction: column; gap: 4px; padding: 6px 8px; border-radius: 8px;
  background: var(--ew-ex-bg);
  box-shadow: inset 3px 0 0 var(--ew-ex-bar);
}
.ex-en {
  color: var(--ink, #1d1d1d); line-height: 1.4;
  font-size: calc(12px * var(--scale-example, 1) * var(--card-font-scale, 1));
}
.ex-cn {
  color: var(--ew-warm-ink); line-height: 1.4;
  font-size: calc(12px * var(--scale-example, 1) * var(--card-font-scale, 1));
}

.action-btn.example-toggle-btn {
  color: var(--ew-fav); background: var(--ew-fav-bg); border-color: var(--ew-fav-line);
  box-shadow: var(--ew-btn-sh), inset 0 1px 0 rgba(255,255,255,.9);
}
.action-btn.example-toggle-btn:hover { background: var(--ew-fav); color: #fff; border-color: var(--ew-fav);
                                       transform: translateY(-2px); box-shadow: 0 7px 15px -4px var(--ew-fav-sh); }
.action-btn.example-toggle-btn.active { background: linear-gradient(135deg, var(--ew-fav), #b45309); color: #fff;
                                        border-color: var(--ew-fav); box-shadow: 0 5px 13px -3px var(--ew-fav-sh); }

/* ---------- 6. 显示/隐藏（原样保留，逻辑在 cardJs） ---------- */
.eye-btn { display: flex; }
.def-cn { display: block; }
.ex-cn { display: block; }
.def-en.hide { display: none; }
.def-cn.hide { display: none; }
.ex-cn.hide { display: none; }

/* ---------- 7. 窄屏：4 个按钮 + 长单词塞不进一行 ----------
   应用的移动端断点就是 640px，此时卡片内宽约 302px，4 个 44px 按钮就要 206px，
   `institutionalization` 这样的长词会被压出去。让按钮整组独占一行。
   ⚠️ 这是全文件唯一一处动了布局的地方；不想要，删掉这一段即可。 */
@media (max-width: 640px) {
  .card-header { flex-wrap: wrap; row-gap: 10px; }
  .actions { flex: 1 0 100%; justify-content: space-between; }
}

/* ---------- 8. 暗色皮肤（Dark / Starry / Sci-Fi）：只重映射变量 ---------- */
body.dark-mode .word-card {
  --ew-h1-deep:#6ee7b7; --ew-h1-soft:rgba(5,150,105,.20);
  --ew-h1-sh:rgba(5,150,105,.45);
  --ew-ink:#a7f3d0;
  --ew-warm-ink:#fdba74;
  --ew-def-bg:rgba(255,255,255,.045); --ew-def-bar:#34d399;
  --ew-ex-bg:rgba(217,119,6,.10);     --ew-ex-bar:#fbbf24;
  --ew-divider:linear-gradient(90deg,rgba(110,231,183,.38) 0%,rgba(103,232,249,.16) 55%,rgba(255,255,255,0) 100%);
  --ew-c1:var(--card-bg); --ew-c2:var(--card-bg);
  --ew-card-line:var(--line);
  --ew-card-sh:0 1px 2px rgba(0,0,0,.35),0 12px 26px -16px rgba(0,0,0,.75);
  --ew-card-sh-up:0 2px 4px rgba(0,0,0,.40),0 20px 34px -18px rgba(0,0,0,.80);
  --ew-btn-line:var(--line); --ew-btn-sh:0 1px 2px rgba(0,0,0,.30);
  --ew-play-bg:rgba(5,150,105,.16);  --ew-play-line:rgba(110,231,183,.34);
  --ew-eye-bg:rgba(8,145,178,.16);   --ew-eye-line:rgba(103,232,249,.30);
  --ew-mark-bg:rgba(225,29,72,.16);  --ew-mark-line:rgba(253,164,175,.30);
  --ew-fav-bg:rgba(217,119,6,.16);   --ew-fav-line:rgba(252,211,77,.30);
}
body.dark-mode .word-card.highlighted {
  background:
    linear-gradient(180deg,#e11d48 0%,#f43f5e 100%) left top / 4px 100% no-repeat,
    radial-gradient(125% 100% at 100% 0%, rgba(244,63,94,.16) 0%, rgba(0,0,0,0) 60%),
    var(--card-bg);
}
body.dark-mode .action-btn { box-shadow: var(--ew-btn-sh); }
body.dark-mode .action-btn:active { box-shadow: 0 1px 2px rgba(0,0,0,.45); }

cardJs:
(function () {
    'use strict';
    function formatParaphrase(text) {
        if (!text) return '';
        try {
            var arr = JSON.parse(text);
            if (Array.isArray(arr)) return arr.join('<br>');
        } catch (e) {}
        return text;
    }
    window.cardTemplate = {
        name: 'English Word Card',
        fields: [
            { key: 'word', label: 'Word', hideable: false },
            { key: 'phonetic_us', label: 'Phonetic' },
            { key: 'paraphrase_en', label: 'English Definition' },
            { key: 'paraphrase_zh', label: 'Chinese Definition' },
            { key: 'examples', label: 'Examples' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var isMarked = data.is_unknown === 1;
            // 未标记的单词默认隐藏整个释义区（英文+中文）；已标记生词常显；眼睛按钮可临时偷看 5 秒
            // 英文释义：已标记常显，未标记仅偷看时显示；中文释义：永远只在偷看（5 秒）时显示
            var peeking = data._showDef === true;
            var enHide = (isMarked || peeking) ? '' : 'hide';
            var zhHide = peeking ? '' : 'hide';
            var eyeActive = peeking ? 'is-active' : '';
            var examplesHtml = '';
            if (!isHidden('examples') && data.data && data.data.examples && data.data.examples.length) {
                examplesHtml += '<div class="divider"></div><div class="examples">';
                data.data.examples.forEach(function (ex, idx) {
                    var showEx = ex._show === true;
                    var exHide = showEx ? '' : 'hide';
                    var btnActive = showEx ? 'active' : '';
                    examplesHtml += '<div class="example-item">';
                    examplesHtml += '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">';
                    examplesHtml += '<div class="ex-en" style="flex:1;word-wrap:break-word;word-break:break-word;">' + (ex.en || '') + '</div>';
                    examplesHtml += '<button class="action-btn eye-btn example-toggle-btn ' + btnActive + '" data-action="toggle-ex" data-ex-idx="' + idx + '" data-tooltip="Show Translation"><i class="fa-solid fa-eye"></i></button></div>';
                    examplesHtml += '<div class="ex-cn ' + exHide + '">' + (ex.zh || '') + '</div>';
                    examplesHtml += '</div>';
                });
                examplesHtml += '</div>';
            }
            var html = '<div class="word-card ' + (data.is_unknown === 1 ? 'highlighted' : '') + '" data-card-id="' + data.id + '">';
            html += '<div class="card-header"><div class="word-basic">';
            html += '<span class="word-index">' + String(data.current_order).padStart(2, '0') + '</span>';
            html += wrap('word', '<span class="word-title">' + (data.data && data.data.word || '') + '</span>');
            html += wrap('phonetic_us', '<span class="word-phonetic">' + (data.data && data.data.phonetic_us || '') + '</span>');
            html += '</div><div class="actions">';
            html += '<button class="action-btn act-play" data-action="play" data-tooltip="Play Pronunciation"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="action-btn eye-btn act-eye ' + eyeActive + '" data-action="toggle-def" data-tooltip="Toggle Chinese"><i class="' + (peeking ? 'fa-solid' : 'fa-regular') + ' fa-eye"></i></button>';
            html += '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="Mark as Unknown"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
            html += '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="Favorite"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>';
            html += '</div></div>';
            if (!isHidden('paraphrase_en') || !isHidden('paraphrase_zh')) {
                html += '<div class="definition">';
                html += wrap('paraphrase_en', '<div class="def-en ' + enHide + '">' + formatParaphrase(data.data && data.data.paraphrase_en) + '</div>');
                html += wrap('paraphrase_zh', '<div class="def-cn ' + zhHide + '">' + formatParaphrase(data.data && data.data.paraphrase_zh) + '</div>');
                html += '</div>';
            }
            html += examplesHtml;
            html += '</div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            cardElement.querySelector('[data-action="play"]').addEventListener('click', function () {
                var w = cardData.data && cardData.data.word;
                if (w) api.playAudio(w);
                api.track('audio_play');
            });
            cardElement.querySelector('[data-action="toggle-def"]').addEventListener('click', function () {
                api.track('definition_view');
                if (cardData._showDef) {
                    clearTimeout(cardData._defTimer);
                    cardData._showDef = false;
                    api.rerender();
                } else {
                    cardData._showDef = true;
                    clearTimeout(cardData._defTimer);
                    cardData._defTimer = setTimeout(function () {
                        cardData._showDef = false;
                        api.rerender();
                    }, 5000);
                    api.rerender();
                }
            });
            cardElement.querySelector('[data-action="mark"]').addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) {
                favBtn.addEventListener('click', function () {
                    api.toggleFavorite().then(function () { api.rerender(); });
                    api.track('favorite_toggle');
                });
            }
            cardElement.querySelectorAll('[data-action="toggle-ex"]').forEach(function (btn) {
                btn.addEventListener('click', function () {
                    var idx = parseInt(btn.dataset.exIdx);
                    var ex = cardData.data && cardData.data.examples && cardData.data.examples[idx];
                    if (!ex) return;
                    if (ex._show) {
                        clearTimeout(ex._timer);
                        ex._show = false;
                        api.rerender();
                    } else {
                        ex._show = true;
                        clearTimeout(ex._timer);
                        ex._timer = setTimeout(function () {
                            ex._show = false;
                            api.rerender();
                        }, 5000);
                        api.rerender();
                        api.track('example_view');
                    }
                });
            });
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var tooltip = btn.dataset.tooltip;
                    if (tooltip && api.showTooltip) api.showTooltip(btn, tooltip);
                });
                btn.addEventListener('mouseleave', function () {
                    if (api.hideTooltip) api.hideTooltip();
                });
